package com.brightloop.quotation;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;
public final class QuotationDtos{private QuotationDtos(){}public record LineRequest(@NotNull Long productId,Long planId,Long variantId,@Min(1) int quantity){}public record Request(@NotNull Long customerId,@Min(1) @Max(365) int validityDays,String paymentTerms,String notes,String discountCode,@NotEmpty List<@Valid LineRequest> lines){}public record Line(Long id,Long productId,String productName,Long planId,String planName,Long variantId,String variantName,int quantity,BigDecimal unitPrice,BigDecimal taxRate,BigDecimal lineSubtotal,BigDecimal lineTax,BigDecimal lineTotal){static Line of(QuotationLine l){return new Line(l.id,l.product.getId(),l.product.getName(),l.plan==null?null:l.plan.getId(),l.plan==null?null:l.plan.getName(),l.variant==null?null:l.variant.getId(),l.variant==null?null:l.variant.getName(),l.quantity,l.unitPrice,l.taxRate,l.lineSubtotal,l.lineTax,l.lineTotal);}}public record Response(Long id,String quotationNumber,Long customerId,String customerName,String customerEmail,String status,LocalDate createdOn,LocalDate expiresOn,String paymentTerms,String notes,BigDecimal subtotal,BigDecimal discountAmount,BigDecimal taxAmount,BigDecimal grandTotal,List<Line> lines){static Response of(Quotation q){return new Response(q.getId(),q.getQuotationNumber(),q.getCustomer().getId(),q.getCustomer().getFullName(),q.getCustomer().getEmail(),q.getStatus(),q.getCreatedOn(),q.getExpiresOn(),q.getPaymentTerms(),q.getNotes(),q.getSubtotal(),q.getDiscountAmount(),q.getTaxAmount(),q.getGrandTotal(),q.getLines().stream().map(Line::of).toList());}}}
